fn solve(n: i8, k: i8) -> Vec<i8> {
    // Number of unselected items
    let unselected = n - k;

    // If no items are selected or all items are selected,
    // the number of "good" unselected items must be zero.
    if k == 0 || k == n {
        vec![0, 0]
    } else {
        // Otherwise, at least one "good" unselected item is possible.
        let x_min = 1;
        // The maximum possible "good" items is min(unselected, 2*k).
        // Use saturating_mul to avoid overflow on i8 when k*2 > i8::MAX.
        let double_k = k.saturating_mul(2);
        let x_max = std::cmp::min(unselected, double_k);
        vec![x_min, x_max]
    }
}